// A dedicated output bus: no microphone, sampled speech or unrelated arcade sound is recorded.
export class AirSliceAudio{
 constructor({contextFactory=()=>new (globalThis.AudioContext||globalThis.webkitAudioContext)()}={}){this.contextFactory=contextFactory;this.sound=.65;this.music=.22;this.muted=false;this.nodes=new Set();this.enabled=false;}
 async enable(){if(!this.context){this.context=this.contextFactory();this.master=this.context.createGain();this.limiter=this.context.createDynamicsCompressor();this.limiter.threshold.value=-16;this.limiter.ratio.value=10;this.master.connect(this.limiter);this.limiter.connect(this.context.destination);}await this.context.resume();this.enabled=true;this.master.gain.value=this.muted?0:1;}
 tone(frequency,time=.12,type='sine',volume=.12,when=0){if(!this.enabled||this.context?.state!=='running')return;const c=this.context,o=c.createOscillator(),g=c.createGain(),at=c.currentTime+when;o.frequency.value=frequency;o.type=type;g.gain.setValueAtTime(.001,at);g.gain.exponentialRampToValueAtTime(Math.max(.001,volume),at+.008);g.gain.exponentialRampToValueAtTime(.001,at+time);o.connect(g);g.connect(this.master);o.start(at);o.stop(at+time+.03);this.nodes.add(o);o.onended=()=>{o.disconnect();g.disconnect();this.nodes.delete(o);};}
 fx(type,count=1){if(this.sound===0)return;const v=this.sound*.2;if(type==='slice'){this.tone(500+Math.random()*150,.055,'triangle',v);this.tone(950,.045,'sine',v*.5,.035);}else if(type==='launch')this.tone(260,.07,'sine',v*.3);else if(type==='combo'||type==='team'){for(let i=0;i<3;i++)this.tone(500+Math.min(count,6)*50+i*170,.15,'triangle',v*.7,i*.06);}else if(type==='crack'){this.tone(175,.07,'triangle',v);this.tone(270,.08,'sine',v,.035);}else if(type==='bomb'){this.tone(75,.25,'triangle',v*.9);this.tone(105,.18,'sine',v,.03);}else if(type==='miss')this.tone(190,.16,'sine',v*.6);else if(type==='power')for(let i=0;i<4;i++)this.tone(390+i*160,.18,'sine',v,i*.045);else if(type==='tick')this.tone(440,.12,'sine',v);else if(type==='go')this.tone(880,.25,'triangle',v);else if(type==='win'||type==='record')for(let i=0;i<5;i++)this.tone([523,659,784,1046,1318][i],.3,'triangle',v*.8,i*.11);else if(type==='end'){this.tone(330,.2,'sine',v);this.tone(262,.35,'sine',v,.2);}}
 playMusic(){this.pauseMusic();if(!this.enabled)return;let step=0;const notes=[261.63,329.63,392,329.63,293.66,349.23,440,392];this.musicTimer=setInterval(()=>{if(this.music>0&&!this.muted){this.tone(notes[step%8],.21,'sine',this.music*.065);if(step%2===0)this.tone(notes[step%8]/2,.27,'triangle',this.music*.08);step++;}},270);}
 pauseMusic(){clearInterval(this.musicTimer);this.musicTimer=null;}
 quiet(){this.pauseMusic();for(const n of this.nodes)try{n.stop();}catch{}this.nodes.clear();}
 dispose(){this.enabled=false;this.quiet();this.context?.close();this.context=null;}
}
